package mugi.bridge;
import java.awt.Component;import java.awt.Container;import java.awt.Window;import java.lang.instrument.Instrumentation;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.nio.file.Path;import javax.swing.*;
public final class CubismComponentDumpAgent{public static void agentmain(String argument,Instrumentation ignored){SwingUtilities.invokeLater(()->{try{StringBuilder o=new StringBuilder();for(Window w:Window.getWindows())if(w.isVisible()){o.append("WINDOW\t").append(w.getClass().getName()).append('\t').append(w instanceof java.awt.Dialog d?d.getTitle():w instanceof java.awt.Frame f?f.getTitle():"").append('\n');dump(o,w,"  ");}Files.writeString(Path.of(argument),o.toString(),StandardCharsets.UTF_8);}catch(Exception e){e.printStackTrace();}});}private static void dump(StringBuilder o,Component c,String p){String t=c instanceof AbstractButton b?b.getText():c instanceof JLabel l?l.getText():c instanceof JTextField f?f.getText():c instanceof JComboBox<?> b?String.valueOf(b.getSelectedItem()):"";o.append(p).append(c.getClass().getName()).append('\t').append(t).append('\t').append(c.isEnabled()).append('\t').append(c.isVisible()).append('\n');if(c instanceof Container n)for(Component x:n.getComponents())dump(o,x,p+"  ");}}
